CREATE COLUMN TABLE "TEST_AP"."ODAB" ("AbsEntry" INTEGER CS_INT NOT NULL , "PackEntry" INTEGER CS_INT NOT NULL , "DashbdCode" NVARCHAR(32) NOT NULL , "DashbdName" NVARCHAR(100), "DashbdPath" NVARCHAR(254), "Note" NCLOB MEMORY THRESHOLD 1000, "Status" NVARCHAR(1) DEFAULT 'A', "JobFlag" NVARCHAR(1) DEFAULT 'N', "JobType" NVARCHAR(1) DEFAULT 'R', "JobSetting" NVARCHAR(100), "RenewDate" LONGDATE CS_LONGDATE, "RenewTime" SMALLINT CS_INT, "ProcName" NVARCHAR(100), "JobName" NVARCHAR(100), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ODAB_CODE" ON "TEST_AP"."ODAB" ( "PackEntry" ASC, "DashbdCode" ASC )